svg.script:

function setStage(index) {
  // 1. Atualizar classe no elemento raiz para acionar estilização do estágio
  var root = document.getElementById('p11-svg-root');
  root.setAttribute('class', 'active-' + index);

  // 2. Preenchimento gradual do trilho do slider
  var trackFill = document.getElementById('slider-track-fill');
  var fillWidths = [0, 120, 240, 360];
  trackFill.setAttribute('width', fillWidths[index]);

  // 3. Atualizar states ativos dos rótulos de tempo
  for (var i = 0; i < 4; i++) {
    var label = document.getElementById('tick-label-' + i);
    if (i === index) {
      label.setAttribute('class', 'slider-tick-label active');
    } else {
      label.setAttribute('class', 'slider-tick-label');
    }
  }

  // 4. Alternar painéis no card clínico lateral
  for (var j = 0; j < 4; j++) {
    var infoPanel = document.getElementById('info-' + j);
    if (j === index) {
      infoPanel.style.display = 'block';
    } else {
      infoPanel.style.display = 'none';
    }
  }
}

// Suporte nativo a navegação acessível por setas do teclado
document.addEventListener('keydown', function(event) {
  var root = document.getElementById('p11-svg-root');
  var currentClass = root.getAttribute('class') || 'active-0';
  var currentStage = parseInt(currentClass.replace('active-', '')) || 0;

  if (event.key === 'ArrowRight' || event.key === 'ArrowUp') {
    if (currentStage < 3) setStage(currentStage + 1);
  } else if (event.key === 'ArrowLeft' || event.key === 'ArrowDown') {
    if (currentStage > 0) setStage(currentStage - 1);
  }
});
